        state.allFilesExcludingDefaultLibraryFile = undefined;
        state.allFileNames = undefined;
    }
const state: BuilderState = { allFilesExcludingDefaultLibraryFile: ["index.ts"], allFileNames: ["index.ts"] };
releaseCache(state);
